const MASK63 = (1n << 63n) - 1n;

/** Шанс «a из b» на генераторе g (spec offline, правило 25): ровно 2 слова. */
function rollU(g) {
  const lo = BigInt(g.u32() >>> 0);
  const hi = BigInt(g.u32() >>> 0);
  return ((hi << 32n) | lo) & MASK63;
}
function chanceU(U, a, b) {
  const den = BigInt(Math.floor(b));
  return Number(U % den) + 1 <= a;
